{
  "src/vok/rules.ts": "// Game rules for Osk and Fen movement

export interface GameState {
  osk: { position: string };
  fen: { position: string };
}

export type Operation =
  | { type: 'reset' }
  | { type: 'advanceOsk'; target: string }
  | { type: 'advanceFen'; target: string }
  | { type: 'advanceOskFen'; target: string };

export const rules = {
  reset(): GameState {
    return {
      osk: { position: 'nim' },
      fen: { position: 'nim' }
    };
  },

  applyOperation(state: GameState, operation: Operation): GameState {
    switch (operation.type) {
      case 'reset':
        return this.reset();
      case 'advanceOsk':
        return {
          ...state,
          osk: { position: operation.target }
        };
      case 'advanceFen':
        return {
          ...state,
          fen: { position: operation.target }
        };
      case 'advanceOskFen':
        return {
          ...state,
          osk: { position: operation.target },
          fen: { position: operation.target }
        };
      default:
        return state;
    }
  }
};
",
  "src/protocol_adapter.ts": "import { rules, type Operation, type GameState } from './vok/rules';

export interface WorldProtocol {
  reset: () => void;
  applyOperation: (operation: Operation) => void;
  getEntityState: (entityId: string) => unknown;
  toAbstractSnapshot: () => unknown;
}

let currentState: GameState = rules.reset();

export const protocol: WorldProtocol = {
  reset(): void {
    currentState = rules.reset();
  },

  applyOperation(operation: Operation): void {
    currentState = rules.applyOperation(currentState, operation);
  },

  getEntityState(entityId: string): unknown {
    if (entityId === 'osk') {
      return currentState.osk;
    }
    if (entityId === 'fen') {
      return currentState.fen;
    }
    return null;
  },

  toAbstractSnapshot(): unknown {
    return {
      state: currentState,
      timestamp: Date.now()
    };
  }
};
"
